/* erg0.js — реалізація за документованим API. Якщо маєш власний erg0.min.js — просто заміни цей файл.
   API: const {render, notify, tags, attrs, handlers} = erg0;
   tags: будь-який тег, приймає примітиви/теги/attrs/handlers у довільному порядку;
   attrs: тільки як template tags: c`active`, value`${x}`;
   handlers: onclick(fn) і т.д., після кожного handler — авто-ререндер.
   Бонус цієї реалізації: після ререндеру відновлюється фокус/каретка елемента з тим самим id. */
(function () {
  const tags = new Proxy({}, { get: (_, name) => (...children) => ({ __t: String(name), children }) });
  const attrs = new Proxy({}, {
    get: (_, name) => (strings, ...vals) => ({
      __a: String(name),
      v: Array.isArray(strings)
        ? strings.reduce((acc, s, i) => acc + s + (i < vals.length ? (vals[i] == null ? '' : vals[i]) : ''), '')
        : String(strings)
    })
  });
  const handlers = new Proxy({}, {
    get: (_, name) => fn => ({ __h: String(name).replace(/^on/, ''), fn })
  });

  let doNotify = null;
  let timer = null;
  function schedule() {
    if (timer) return;
    timer = setTimeout(() => { timer = null; if (doNotify) doNotify(); }, 0);
  }

  function build(n) {
    if (n == null || n === false || n === true) return document.createTextNode('');
    if (Array.isArray(n)) {
      const f = document.createDocumentFragment();
      for (const c of n) f.appendChild(build(c));
      return f;
    }
    if (typeof n === 'object' && n.__t) {
      const el = document.createElement(n.__t);
      apply(el, n.children);
      return el;
    }
    return document.createTextNode(String(n));
  }

  function apply(el, children) {
    for (const c of children) {
      if (c == null || c === false || c === true) continue;
      if (Array.isArray(c)) { apply(el, c); continue; }
      if (typeof c === 'object' && c.__a !== undefined) {
        if (c.__a === 'value') el.value = c.v;
        else if (c.__a === 'checked') el.checked = c.v !== 'false';
        else el.setAttribute(c.__a, c.v);
      } else if (typeof c === 'object' && c.__h) {
        el.addEventListener(c.__h, e => { c.fn(e); schedule(); });
      } else {
        el.appendChild(build(c));
      }
    }
  }

  function render(root, component) {
    doNotify = function () {
      const ae = document.activeElement;
      const fid = ae && root.contains(ae) && ae.id ? ae.id : null;
      let val = null, s = null, e = null;
      if (fid && 'value' in ae) {
        val = ae.value;
        if ('selectionStart' in ae) { try { s = ae.selectionStart; e = ae.selectionEnd; } catch (_) {} }
      }
      root.replaceChildren(build(component()));
      if (fid) {
        const el = document.getElementById(fid);
        if (el) {
          el.focus();
          if (val != null && 'value' in el) {
            el.value = val;
            if (s != null) { try { el.setSelectionRange(s, e); } catch (_) {} }
          }
        }
      }
    };
    doNotify();
    return doNotify;
  }

  window.erg0 = { render, tags, attrs, handlers, notify: schedule };
})();
